/* @jsx h */
import type { EngineInterface, Register } from 'claude-code'
import { HABITATS, KIND_COLOR, KIND_ICON, RARITY_STARS, SPECIES, byName, type Kind } from './dex/data.ts'
import {
  BALLS_PER_ENCOUNTER, dexSize, gainXp, habitatOf, isPolite, levelOf, pickWild, record,
  rollEncounter, throwBall, totalSpecies, xpEventFor, xpForLevel, type Dex, type Partner, type XpEvent,
} from './dex/logic.ts'

// cc-pokedex: wild ones appear above the prompt depending on where your prompt leads (water words,
// grass words, a bug to fix, a plan to think through...). Throw balls to catch them, keep a dex in
// $.store, and pick a partner: it draws under the logo, beside the spinner, and above the prompt,
// and levels up and evolves as Claude works. Nothing here asks the model anything.
//
// Two rules for the boards in ./boards: never name a local `h` (JSX compiles to calls of `h`), and
// `Client` module paths must be string literals (the engine reads them off the source).

type Phase = 'wild' | 'throwing' | 'caught' | 'fled'
type Encounter = {
  name: string
  kind: Kind
  where: string
  ballsLeft: number
  phase: Phase
  /** bumped on every throw; the board animates when it sees a new one */
  throwSeq: number
  shakes: number
  /** decided at the throw, revealed once the animation has played */
  pending?: boolean
}

let dex: Dex = {}
let partner: Partner | undefined
let showPartner = true
let encounter: Encounter | undefined
let firstNotice: string | undefined
// a lure: the next prompt that leads into this species' habitat brings it out
let lure: string | undefined

const isDex = (v: unknown): v is Dex => typeof v === 'object' && v !== null && !Array.isArray(v)
const isPartner = (v: unknown): v is Partner => typeof v === 'object' && v !== null && typeof (v as Partner).xp === 'number' && typeof (v as Partner).name === 'string'

const stars = (name: string) => RARITY_STARS[byName(name)?.rarity ?? 'common']
const icon = (name: string) => KIND_ICON[byName(name)?.kind ?? 'normal']

async function save($: EngineInterface, key: string, value: unknown) {
  await $.store.set(key, value).catch(err => $.ui.log(`cc-pokedex: store write failed: ${err}`))
}

// one throw: decide now, animate on the board, reveal when the animation has played
async function throwNow($: EngineInterface): Promise<string> {
  if (!encounter || encounter.phase !== 'wild') return encounter?.phase === 'throwing' ? 'the ball is still in the air' : 'nothing to throw at · a wild one appears when you prompt'
  const sp = byName(encounter.name)
  if (!sp) return 'nothing to throw at'
  const { caught, shakes } = throwBall(sp.rarity, Math.random)
  encounter = { ...encounter, phase: 'throwing', throwSeq: encounter.throwSeq + 1, shakes, ballsLeft: encounter.ballsLeft - 1, pending: caught }
  $.ui.invalidate('ui.render')
  // the board's clock: four frames of flight, three per shake, at 200 ms, then a beat
  const ms = 800 + shakes * 600 + 400
  $.clock.after(ms, () => { void reveal($) })
  return `threw a ball at ${sp.name}...`
}

async function reveal($: EngineInterface) {
  if (!encounter || encounter.phase !== 'throwing') return
  const name = encounter.name
  if (encounter.pending) {
    encounter = { ...encounter, phase: 'caught' }
    const now = await $.clock.now()
    const { dex: next, isNew } = record(dex, name, now)
    dex = next
    await save($, 'dex', dex)
    $.ui.toast(`${icon(name)} Gotcha! ${name} was caught${isNew ? ` · new dex entry (${dexSize(dex)}/${totalSpecies})` : ''}`)
    if (!partner) {
      partner = { name, caughtAs: name, xp: 0, since: now }
      await save($, 'partner', partner)
      $.ui.toast(`${name} is now your partner · /dex partner <name> switches`)
    } else {
      await feedPartner($, 'catch')
    }
    $.ui.invalidate('ui.render')
    $.clock.after(4000, () => { if (encounter?.phase === 'caught') { encounter = undefined; $.ui.invalidate('ui.render') } })
  } else if (encounter.ballsLeft <= 0) {
    encounter = { ...encounter, phase: 'fled' }
    $.ui.toast(`${name} broke free and ran away`)
    $.ui.invalidate('ui.render')
    $.clock.after(3000, () => { if (encounter?.phase === 'fled') { encounter = undefined; $.ui.invalidate('ui.render') } })
  } else {
    encounter = { ...encounter, phase: 'wild' }
    $.ui.invalidate('ui.render')
  }
}

async function feedPartner($: EngineInterface, event: XpEvent) {
  if (!partner) return
  const { partner: fed, leveled, evolvedFrom } = gainXp(partner, event)
  partner = fed
  await save($, 'partner', partner)
  if (evolvedFrom) {
    $.ui.toast(`✨ What? ${evolvedFrom} is evolving... it became ${fed.name}!`)
    const now = await $.clock.now()
    const { dex: next } = record(dex, fed.name, now)
    dex = next
    await save($, 'dex', dex)
  } else if (leveled) {
    $.ui.toast(`${icon(fed.name)} ${fed.name} grew to level ${levelOf(fed.xp)}`)
  }
  if (leveled || evolvedFrom) $.ui.invalidate('ui.render')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    const stored = (key: string) => $.store.get(key).catch(err => { $.ui.log(`cc-pokedex: store read failed: ${err}`); return undefined })
    const savedDex = await stored('dex')
    if (isDex(savedDex)) dex = savedDex
    const savedPartner = await stored('partner')
    if (isPartner(savedPartner)) partner = savedPartner
    showPartner = (await stored('show')) !== false
    await $.command.register({
      name: 'dex',
      description: 'Pokedex: status, list, partner <name>, throw, run, lure <name>, show, hide (cc-pokedex)',
      argumentHint: '[list | partner <name> | throw | run | lure <name> | show | hide]',
      immediate: true,
    }).catch(err => $.ui.log(`cc-pokedex: /dex not registered: ${err}`))
    return r
  })

  // where the prompt leads decides what may show up; the prompt itself passes through untouched
  on('prompt.submit', async ($, e, next) => {
    try {
      const text = e.text.trim()
      if (e.origin.kind === 'composer' && !text.startsWith('/') && text.length > 0 && (!encounter || encounter.phase === 'fled' || encounter.phase === 'caught')) {
        const { kind, where } = habitatOf(text)
        const lured = lure ? byName(lure) : undefined
        if (lured && lured.kind === kind) {
          lure = undefined
          encounter = { name: lured.name, kind: lured.kind, where, ballsLeft: BALLS_PER_ENCOUNTER, phase: 'wild', throwSeq: 0, shakes: 0 }
          $.ui.toast(`${KIND_ICON[lured.kind]} The lure worked! A wild ${lured.name} appeared ${where}!`)
          $.ui.invalidate('ui.render')
        } else if (rollEncounter(kind, Math.random)) {
          const sp = pickWild(kind, Math.random, isPolite(text))
          encounter = { name: sp.name, kind: sp.kind, where, ballsLeft: BALLS_PER_ENCOUNTER, phase: 'wild', throwSeq: 0, shakes: 0 }
          $.ui.toast(`${KIND_ICON[sp.kind]} A wild ${sp.name} appeared ${where}! Click it or /dex throw`)
          $.ui.invalidate('ui.render')
        }
      }
    } catch (err) {
      $.ui.log(`cc-pokedex: encounter roll failed: ${err}`)
    }
    return next(e)
  })

  on('command.run', { command: 'dex' }, async ($, e, next) => {
    const [verb = '', ...rest] = e.args.trim().split(/\s+/)
    const arg = rest.join(' ')
    const v = verb.toLowerCase()
    const status = () => {
      const p = partner
      const me = p ? `partner ${icon(p.name)} ${p.name} · level ${levelOf(p.xp)} · ${p.xp} xp (next at ${xpForLevel(levelOf(p.xp) + 1)})` : 'no partner yet · catch one and it joins you'
      const wild = encounter && encounter.phase !== 'caught' && encounter.phase !== 'fled' ? `wild ${encounter.name} ${encounter.where} · ${encounter.ballsLeft} balls left · /dex throw or click it` : 'nothing wild right now · prompt about water, grass, fire, bugs, plans, builds...'
      return `dex ${dexSize(dex)}/${totalSpecies} · ${me}\n${wild}`
    }
    if (v === '' || v === 'status') return { text: status() }
    if (v === 'list') {
      const rows = SPECIES.filter(sp => dex[sp.name]).map(sp => {
        const d = dex[sp.name]!
        return `${KIND_ICON[sp.kind]} ${sp.name.padEnd(12)} ${RARITY_STARS[sp.rarity].padEnd(4)} ${sp.kind.padEnd(9)} x${d.count}${partner?.name === sp.name ? ' · partner' : ''}`
      })
      return { text: rows.length ? [`caught ${rows.length}/${totalSpecies}`, ...rows].join('\n') : 'nothing caught yet · a wild one appears when your prompt leads somewhere' }
    }
    if (v === 'partner') {
      if (!arg) return { text: partner ? `partner is ${partner.name} · /dex partner <name> switches to another you caught` : 'no partner yet' }
      const sp = byName(arg)
      if (!sp) return { text: `no species called "${arg}"` }
      if (!dex[sp.name]) return { text: `you have not caught ${sp.name} yet` }
      const now = await $.clock.now()
      partner = { name: sp.name, caughtAs: sp.name, xp: 0, since: now }
      await save($, 'partner', partner)
      firstNotice = undefined
      $.ui.invalidate('ui.render')
      return { text: `${KIND_ICON[sp.kind]} ${sp.name} is now your partner` }
    }
    if (v === 'throw') return { text: await throwNow($) }
    if (v === 'run') {
      if (!encounter || encounter.phase === 'caught' || encounter.phase === 'fled') return { text: 'nothing to run from' }
      const name = encounter.name
      encounter = undefined
      $.ui.invalidate('ui.render')
      return { text: `got away from ${name}` }
    }
    if (v === 'show' || v === 'hide') {
      showPartner = v === 'show'
      await save($, 'show', showPartner)
      $.ui.invalidate('ui.render')
      return { text: showPartner ? 'partner shown above the prompt' : 'partner hidden above the prompt (still by the spinner)' }
    }
    if (v === 'wild') {
      // for trying it out: force an encounter, optionally of a kind or a species
      const sp = byName(arg) ?? pickWild((Object.keys(KIND_COLOR) as Kind[]).includes(arg as Kind) ? (arg as Kind) : 'normal', Math.random, true)
      const where = habitatOf(arg).where
      encounter = { name: sp.name, kind: sp.kind, where, ballsLeft: BALLS_PER_ENCOUNTER, phase: 'wild', throwSeq: 0, shakes: 0 }
      $.ui.invalidate('ui.render')
      return { text: `${KIND_ICON[sp.kind]} A wild ${sp.name} appeared ${where}!` }
    }
    if (v === 'lure') {
      const sp = byName(arg)
      if (!sp) return { text: arg ? `no species called "${arg}"` : 'lure what? /dex lure pikachu' }
      lure = sp.name
      const where = HABITATS.find(h => h.kind === sp.kind)?.where ?? 'on the road'
      return { text: `${KIND_ICON[sp.kind]} lure set for ${sp.name} · your next prompt that leads ${where} brings it out` }
    }
    if (v === 'release') {
      if (!partner) return { text: 'no partner to release' }
      const name = partner.name
      partner = undefined
      await save($, 'partner', undefined)
      $.ui.invalidate('ui.render')
      return { text: `${name} went back to the wild` }
    }
    return { text: 'dex · list · partner <name> · throw · run · show · hide · lure <name> · wild [kind|name] · release' }
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    await feedPartner($, 'turn')
    return r
  })

  on('tool.call', async ($, e, next) => {
    const r = await next(e)
    const command = (e as { command?: unknown }).command
    const event = xpEventFor(e.tool, typeof command === 'string' ? command : undefined, 'deny' in r ? undefined : !r.isError)
    if (event) await feedPartner($, event)
    return r
  })

  // the encounter board posts a click; the partner board posts nothing
  on('ui.message', async ($, e, next) => {
    const data = e.data as { throw?: unknown; run?: unknown } | null
    if (data?.throw) await throwNow($)
    else if (data?.run) { encounter = undefined; $.ui.invalidate('ui.render') }
    else return next(e)
    return {}
  })

  // above the prompt: the wild one while there is one, else the partner strip
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || e.surface !== 'terminal') return next(e)
    const { Box, Button, Client, Text } = await $.ui.resolve(e)
    const cols = e.props.bodyColumns ?? e.viewport?.columns ?? 80
    if (encounter) {
      const sp = byName(encounter.name)
      if (!sp) return next(e)
      const props = {
        name: sp.name, art: sp.art, color: KIND_COLOR[sp.kind], where: encounter.where, stars: RARITY_STARS[sp.rarity],
        phase: encounter.phase, throwSeq: encounter.throwSeq, shakes: encounter.shakes, ballsLeft: encounter.ballsLeft,
        caught: encounter.phase === 'caught',
      }
      const canThrow = encounter.phase === 'wild'
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={1}>
            {canThrow ? <Button key="dex:throw" label="throw ball" onPress={() => { void throwNow($) }} /> : null}
            {canThrow ? <Button key="dex:run" label="run" onPress={() => { encounter = undefined; $.ui.invalidate('ui.render') }} /> : null}
          </Box>
          <Client key="dex:encounter" module="./boards/encounter.tsx" width={cols} height={4} props={props} />
          {await next(e)}
        </Box>
      )
    }
    if (partner && showPartner) {
      const sp = byName(partner.name)
      if (!sp) return next(e)
      const props = {
        name: sp.name, art: sp.art, color: KIND_COLOR[sp.kind], kind: sp.kind, level: levelOf(partner.xp), xp: partner.xp,
        next: xpForLevel(levelOf(partner.xp) + 1), caught: dexSize(dex), total: totalSpecies, working: e.props.isWorking,
      }
      return (
        <Box flexDirection="column">
          <Client key="dex:partner" module="./boards/partner.tsx" width={cols} height={3} props={props} />
          {await next(e)}
        </Box>
      )
    }
    return next(e)
  })

  // the spinner's word while Claude works: "Pikachu is sauteing... (12s)"
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    if (!partner || e.surface !== 'terminal') return next(e)
    const word = e.props.word
    return next({ ...e, props: { ...e.props, word: `${partner.name} is ${word.charAt(0).toLowerCase()}${word.slice(1)}` } })
  })

  // the line that closes a turn: "Pikachu baked for 3s"
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    if (!partner || e.surface !== 'terminal') return next(e)
    const word = e.props.word
    return next({ ...e, props: { ...e.props, word: `${partner.name} ${word.charAt(0).toLowerCase()}${word.slice(1)}` } })
  })

  // under the logo: the partner beside the first notice line. The logo itself has no render site
  // yet, so this is the nearest a plugin gets to changing the mascot.
  on('ui.render', { component: 'InfoNotice' }, async ($, e, next) => {
    if (!partner || e.surface !== 'terminal') return next(e)
    if (firstNotice === undefined) firstNotice = e.requestId
    if (firstNotice !== e.requestId) return next(e)
    const sp = byName(partner.name)
    if (!sp) return next(e)
    const { Box, Text } = await $.ui.resolve(e)
    const color = KIND_COLOR[sp.kind]
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={2}>
          <Box flexDirection="column">
            {sp.art.map(line => <Text color={color}>{line}</Text>)}
          </Box>
          <Box flexDirection="column" justifyContent="center">
            <Text bold color={color}>{`${sp.name}`}<Text dimColor>{` · level ${levelOf(partner.xp)} · your partner`}</Text></Text>
            <Text dimColor>{`dex ${dexSize(dex)}/${totalSpecies} · /dex`}</Text>
          </Box>
        </Box>
        {await next(e)}
      </Box>
    )
  })
}

