// The game's rules, pure: which habitat a prompt leads to, whether a wild one appears, whether a
// ball catches it, and how a partner levels and evolves. Randomness comes in as an `rng` in
// [0, 1), so tests can pin it. ../register.tsx wires these to the engine.

import { CATCH_RATE, HABITATS, RARITY_WEIGHT, SPECIES, byName, type Kind, type Rarity, type Species } from './data.ts'

export type Rng = () => number

/** The habitat a prompt leads to: the kind with the most matching words, else normal. */
export function habitatOf(text: string): { kind: Kind; where: string } {
  let best: { kind: Kind; where: string; score: number } | undefined
  for (const h of HABITATS) {
    const re = new RegExp(h.words.source, 'gi')
    const score = (text.match(re) ?? []).length
    if (score > 0 && (!best || score > best.score)) best = { kind: h.kind, where: h.where, score }
  }
  return best ? { kind: best.kind, where: best.where } : { kind: 'normal', where: 'on the road' }
}

// how often a prompt in a habitat meets something: named habitats often, the road rarely
export const ENCOUNTER_RATE: Record<'habitat' | 'road', number> = { habitat: 0.4, road: 0.1 }

/** Whether a wild one shows up for this prompt. Mew only answers manners. */
export function rollEncounter(kind: Kind, rng: Rng): boolean {
  return rng() < (kind === 'normal' ? ENCOUNTER_RATE.road : ENCOUNTER_RATE.habitat)
}

const isMythical = (sp: Species) => sp.name === 'Mew'
export const isPolite = (text: string) => /\bplease\b/i.test(text) && /\bthank(s| you)\b/i.test(text)

/** Picks a wild species of a kind, weighted by rarity. Evolved forms roam too, at their rarity. */
export function pickWild(kind: Kind, rng: Rng, polite = false): Species {
  const pool = SPECIES.filter(sp => sp.kind === kind && (!isMythical(sp) || polite))
  const candidates = pool.length ? pool : SPECIES.filter(sp => sp.kind === 'normal')
  const total = candidates.reduce((sum, sp) => sum + RARITY_WEIGHT[sp.rarity], 0)
  let roll = rng() * total
  for (const sp of candidates) {
    roll -= RARITY_WEIGHT[sp.rarity]
    if (roll < 0) return sp
  }
  return candidates[candidates.length - 1]!
}

export const BALLS_PER_ENCOUNTER = 4

/** One throw: caught or broke free, and how many times the ball shook (0-3) before the answer. */
export function throwBall(rarity: Rarity, rng: Rng): { caught: boolean; shakes: number } {
  const caught = rng() < CATCH_RATE[rarity]
  if (caught) return { caught, shakes: 3 }
  // a miss shakes fewer times the rarer the target, so the animation tells you how close it was
  const closeness = rng()
  const shakes = closeness < 0.4 ? 0 : closeness < 0.75 ? 1 : 2
  return { caught: false, shakes }
}

// ── the partner ───────────────────────────────────────────────────────────────

export type Partner = {
  /** the species name as it stands (evolution rewrites it) */
  name: string
  /** the species it was caught as */
  caughtAs: string
  xp: number
  since: number
}

export type XpEvent = 'turn' | 'edit' | 'test-pass' | 'commit' | 'catch'
export const XP: Record<XpEvent, number> = { turn: 8, edit: 1, 'test-pass': 10, commit: 15, catch: 20 }

/** level n needs 2·n² xp: 5 at 50, 10 at 200, 16 at 512, 36 at 2592 */
export const levelOf = (xp: number) => Math.max(1, Math.floor(Math.sqrt(xp / 2)))
export const xpForLevel = (level: number) => 2 * level * level

/** Gives xp; when the level crosses an evolution, the partner becomes the next form. */
export function gainXp(p: Partner, event: XpEvent): { partner: Partner; leveled: boolean; evolvedFrom?: string } {
  const before = levelOf(p.xp)
  const xp = p.xp + XP[event]
  const after = levelOf(xp)
  let name = p.name
  let evolvedFrom: string | undefined
  // one evolution per gain; a chain climbs one step per level crossing
  const sp = byName(name)
  if (sp?.evolves && after >= sp.evolves.at && before < sp.evolves.at) {
    evolvedFrom = name
    name = sp.evolves.to
  }
  return { partner: { ...p, xp, name }, leveled: after > before, evolvedFrom }
}

/** What a finished tool call is worth to the partner; undefined when nothing. */
const TEST_COMMAND = /\b(bun|npm|pnpm|yarn)\s+(run\s+)?test\b|\bnpx\s+(jest|vitest|mocha)\b|\b(pytest|jest|vitest|rspec|phpunit|mocha)\b|\bgo\s+test\b|\bcargo\s+test\b|\bmake\s+test\b/
export function xpEventFor(tool: string, command: string | undefined, ok: boolean | undefined): XpEvent | undefined {
  if (!ok) return undefined
  if (tool === 'Bash' && command) {
    if (TEST_COMMAND.test(command)) return 'test-pass'
    if (/\bgit\s+commit\b/.test(command) && !/--dry-run\b/.test(command)) return 'commit'
    return undefined
  }
  if (tool === 'Edit' || tool === 'Write' || tool === 'NotebookEdit') return 'edit'
  return undefined
}

// ── the dex ───────────────────────────────────────────────────────────────────

/** Caught species by name: how many, and when the first one was caught. */
export type Dex = Record<string, { count: number; first: number }>

export function record(dex: Dex, name: string, now: number): { dex: Dex; isNew: boolean } {
  const had = dex[name]
  return {
    dex: { ...dex, [name]: { count: (had?.count ?? 0) + 1, first: had?.first ?? now } },
    isNew: !had,
  }
}

export const dexSize = (dex: Dex) => Object.keys(dex).length
export const totalSpecies = SPECIES.length

