/* @jsx h */
import type { ClientSurface } from 'claude-code'

// The wild one, drawn above the prompt. The hooks module owns the encounter (it decides each throw
// and reveals the answer once this animation has played); this board draws the creature, the ball
// in flight and its shakes, and posts a click as a throw. Space or Enter throws once the board has
// the keyboard (click it first); `r` runs.

type Props = {
  name: string
  art: [string, string, string]
  color: string
  where: string
  stars: string
  phase: 'wild' | 'throwing' | 'caught' | 'fled'
  throwSeq: number
  shakes: number
  ballsLeft: number
  caught: boolean
} | undefined

type State = { frame: number; seenSeq: number; animFrame: number }

const FLIGHT = 4
const PER_SHAKE = 3
const BALL = ['(o)', '(O)', '(o)']
const FLIGHT_PATH = ['   ', '  .', ' . ', '.  ']

export default function EncounterBoard(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ frame: 0, seenSeq: props?.throwSeq ?? 0, animFrame: -1 })
    surface.every(200, () => {
      const s = surface.state
      if (s) surface.setState({ ...s, frame: s.frame + 1, animFrame: s.animFrame >= 0 ? s.animFrame + 1 : -1 })
    })
    surface.onPointer(ev => {
      if (ev.type === 'down') surface.post({ throw: true })
    })
    surface.onKey(ev => {
      if (ev.key === ' ' || ev.key === 'return') surface.post({ throw: true })
      else if (ev.key === 'r') surface.post({ run: true })
    })
  }

  const s = surface.state
  if (!props || !s) return <Text dimColor>a wild one is loading...</Text>

  // a new throw starts the animation from the first frame
  if (props.throwSeq !== s.seenSeq) surface.setState({ ...s, seenSeq: props.throwSeq, animFrame: 0 })
  const anim = props.throwSeq !== s.seenSeq ? 0 : s.animFrame
  const inFlight = props.phase === 'throwing' && anim >= 0 && anim < FLIGHT
  const shaking = props.phase === 'throwing' && anim >= FLIGHT
  const shakeIndex = shaking ? Math.floor((anim - FLIGHT) / PER_SHAKE) : -1
  const shakesDone = Math.min(props.shakes, Math.max(0, shakeIndex + (shaking && (anim - FLIGHT) % PER_SHAKE === PER_SHAKE - 1 ? 1 : 0)))

  // the creature bobs while wild, hides in the ball while it shakes, and blinks now and then
  const bob = props.phase === 'wild' && s.frame % 6 < 3 ? ' ' : ''
  const blink = s.frame % 25 === 0
  const art = props.art.map(line => (blink ? line.replace(/o/g, '-') : line))
  const hidden = shaking || props.phase === 'caught'

  let ball: string
  let line: string
  if (props.phase === 'caught') {
    ball = ' (*) '
    line = `Gotcha! ${props.name} was caught!`
  } else if (props.phase === 'fled') {
    ball = '     '
    line = `Oh no! ${props.name} broke free and ran away.`
  } else if (inFlight) {
    ball = FLIGHT_PATH[anim] + BALL[anim % 3]
    line = 'you threw a ball...'
  } else if (shaking) {
    const wobble = (anim - FLIGHT) % PER_SHAKE
    ball = wobble === 0 ? ' (o) ' : wobble === 1 ? '(o)  ' : '  (o)'
    line = `${'shake '.repeat(shakesDone)}${shakesDone < props.shakes || props.shakes < 3 ? '...' : ''}`
  } else {
    ball = '     '
    line = `${props.ballsLeft} ball${props.ballsLeft === 1 ? '' : 's'} left · click the board or press Space to throw · r runs`
  }

  const color = props.color
  return (
    <Box flexDirection="column">
      <Text bold color={color}>{`A wild ${props.name} appeared ${props.where}! `}<Text color="yellow">{props.stars}</Text></Text>
      <Box flexDirection="row" columnGap={2}>
        <Box flexDirection="column" width={16}>
          {hidden
            ? [<Text> </Text>, <Text color="red">{`     ${ball}`}</Text>, <Text> </Text>]
            : art.map(l => <Text color={color}>{`${bob}${l}`}</Text>)}
        </Box>
        <Box flexDirection="column" justifyContent="flex-end">
          {inFlight ? <Text color="red">{ball}</Text> : <Text> </Text>}
          <Text dimColor={!props.caught} color={props.caught ? 'greenBright' : undefined} bold={props.caught}>{line}</Text>
        </Box>
      </Box>
    </Box>
  )
}

