/* @jsx h */
import type { ClientSurface } from 'claude-code'

// The partner strip above the prompt: the sprite, bobbing while Claude works, blinking now and
// then, with its level and the dex count beside it. Draws only; the hooks module owns the partner.

type Props = {
  name: string
  art: [string, string, string]
  color: string
  kind: string
  level: number
  xp: number
  next: number
  caught: number
  total: number
  working: boolean
} | undefined

type State = { frame: number; petted: number }

const bar = (xp: number, next: number, level: number) => {
  const from = 2 * level * level
  const span = Math.max(1, next - from)
  const filled = Math.round(Math.max(0, Math.min(1, (xp - from) / span)) * 12)
  return '█'.repeat(filled) + '░'.repeat(12 - filled)
}

export default function PartnerBoard(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ frame: 0, petted: 0 })
    surface.every(250, () => {
      const s = surface.state
      if (s) surface.setState({ frame: s.frame + 1, petted: Math.max(0, s.petted - 1) })
    })
    surface.onPointer(ev => {
      const s = surface.state
      if (s && ev.type === 'down') surface.setState({ ...s, petted: 6 })
    })
  }

  const s = surface.state
  if (!props || !s) return <Text dimColor>partner loading...</Text>

  const bob = props.working && s.frame % 4 < 2 ? ' ' : ''
  const blink = s.frame % 20 === 0
  const art = props.art.map(line => (blink ? line.replace(/o/g, '-') : line))
  const hearts = s.petted > 0 ? '  ♥ ♥' : ''

  return (
    <Box flexDirection="row" columnGap={2}>
      <Box flexDirection="column" width={14}>
        {art.map(line => <Text color={props.color}>{`${bob}${line}`}</Text>)}
      </Box>
      <Box flexDirection="column">
        <Text bold color={props.color}>{props.name}<Text dimColor>{` · ${props.kind} · level ${props.level}`}</Text><Text color="magentaBright">{hearts}</Text></Text>
        <Text dimColor>{'xp '}<Text color={props.color}>{bar(props.xp, props.next, props.level)}</Text>{` ${props.xp}/${props.next}`}</Text>
        <Text dimColor>{`dex ${props.caught}/${props.total} · ${props.working ? 'working with Claude' : 'waiting for a prompt'} · /dex hide`}</Text>
      </Box>
    </Box>
  )
}

